#ifndef MEP_RUST_LSP_H
#define MEP_RUST_LSP_H

// The analysis half of mep's own Rust language server (the wire half is
// rust_lsp_server.cpp, the `mep-rust-lsp` binary; the `rust_ls` entry
// in main.cpp's kBuiltinLsp spawns it). Everything here is a pure function
// of the document text, so the whole server is testable without a client
// (rust_lsp_test.cpp). Positions are 0-based lines and 0-based byte
// columns (`positionEncoding: "utf-8"`).
//
// Generated by tools/new_language.py; nix_lsp.h is the worked example of
// every function below.

#include <memory>
#include <string>
#include <vector>

struct RustLspRange {
    int line = 0, col = 0, end_line = 0, end_col = 0;
};

class RustLspDocument;

/** @brief Parses and analyses a document; every query below runs on the result. */
std::shared_ptr<const RustLspDocument> RustLspAnalyze(const std::vector<std::string> &lines);

// --- Diagnostics ------------------------------------------------------------------

enum class RustLspSeverity { Error = 1, Warning = 2, Information = 3, Hint = 4 };

struct RustLspDiagnostic {
    RustLspRange range;
    RustLspSeverity severity = RustLspSeverity::Error;
    std::string code;  // stable id: syntax-error, ...
    std::string message;
    bool unnecessary = false;  // LSP DiagnosticTag.Unnecessary
    bool deprecated = false;   // LSP DiagnosticTag.Deprecated
};

std::vector<RustLspDiagnostic> RustLspDiagnostics(const RustLspDocument &doc);
/** @brief `path:line:col: severity: message [code]`, 1-based, as `--lint` prints it. */
std::string RustLspFormatDiagnostic(const std::string &path, const RustLspDiagnostic &d);
/** @brief Whether a diagnostic makes `--lint` exit non-zero (an error or a warning). */
bool RustLspDiagnosticFails(const RustLspDiagnostic &d);

// --- Completion / hover / signature help -------------------------------------------

enum class RustLspKind {
    Text = 1, Method = 2, Function = 3, Field = 5, Variable = 6, Class = 7, Module = 9, Property = 10,
    Value = 12, Keyword = 14, Snippet = 15, Constant = 21, Struct = 22,
};

struct RustLspCompletionItem {
    std::string label;
    std::string insert_text;
    RustLspKind kind = RustLspKind::Text;
    std::string detail;
    std::string documentation;
    int replace_start = 0, replace_end = 0;  // byte columns on the request's line
};

std::vector<RustLspCompletionItem> RustLspCompletions(const RustLspDocument &doc, int line, int col);

struct RustLspHoverInfo {
    bool found = false;
    std::string text;  // markdown
    RustLspRange range;
};

RustLspHoverInfo RustLspHover(const RustLspDocument &doc, int line, int col);

struct RustLspSignatureHelp {
    bool found = false;
    std::string label;
    std::vector<std::string> params;  // substrings of label
    std::string documentation;
    int active_param = 0;
};

RustLspSignatureHelp RustLspSignatureAt(const RustLspDocument &doc, int line, int col);

// --- Navigation -------------------------------------------------------------------------

struct RustLspLocation {
    RustLspRange range;
};

std::vector<RustLspLocation> RustLspDefinition(const RustLspDocument &doc, int line, int col);

struct RustLspReference {
    RustLspRange range;
    bool is_definition = false;
};

std::vector<RustLspReference> RustLspReferences(const RustLspDocument &doc, int line, int col);

struct RustLspTextEdit {
    RustLspRange range;
    std::string new_text;
};

struct RustLspRenameTarget {
    bool found = false;
    RustLspRange range;
    std::string placeholder;
};

RustLspRenameTarget RustLspPrepareRename(const RustLspDocument &doc, int line, int col);
std::vector<RustLspTextEdit> RustLspRename(const RustLspDocument &doc, int line, int col,
                                               const std::string &new_name, std::string *error);

// --- Outline / folding --------------------------------------------------------------------

enum class RustLspSymbolKind {
    File = 1, Module = 2, Namespace = 3, Class = 5, Method = 6, Property = 7, Field = 8, Function = 12,
    Variable = 13, Constant = 14, String = 15, Number = 16, Boolean = 17, Array = 18, Object = 19, Key = 20,
    Null = 21,
};

struct RustLspSymbol {
    std::string name;
    std::string detail;
    RustLspSymbolKind kind = RustLspSymbolKind::Variable;
    RustLspRange range;
    RustLspRange sel_range;
    int parent = -1;
};

std::vector<RustLspSymbol> RustLspSymbols(const RustLspDocument &doc);

struct RustLspFold {
    int start_line = 0, end_line = 0;
    std::string kind;  // "" or "comment"
};

std::vector<RustLspFold> RustLspFolds(const RustLspDocument &doc);

// --- Formatting ------------------------------------------------------------------------------

/** @brief The formatter as one edit over the changed lines; none when already formatted. */
std::vector<RustLspTextEdit> RustLspFormat(const std::vector<std::string> &lines, int width, std::string *error);

#endif  // MEP_RUST_LSP_H
